// Package tray shows darkbot in the Windows notification area (system
// tray): left click opens the window, the menu offers open, install update
// and quit. Other systems have no tray here (Supported reports false and
// every function does nothing).
//
// The icon is icon.ico, generated by icon.py.
package tray

import _ "embed"

//go:embed icon.ico
var icon []byte

// Texts are the visible strings, already translated.
type Texts struct {
	Tooltip string // hover text of the icon
	Open    string
	Quit    string
	// Update is the menu entry for an available update; "" hides it.
	Update string
}

// Handlers run when the user picks a menu entry or clicks the icon.
// They run on the tray's own goroutine.
type Handlers struct {
	Open   func()
	Update func()
	Quit   func()
}
